// Spørgsmål til Transportjura-quiz.
// a = rigtigt svar (står altid først her, svarene blandes på siden).
// k = emne, q = spørgsmål, o = svarmuligheder, f = forklaring, p = paragraf.
window.QUESTIONS = [
// ===================== GRUNDBEGREBER =====================
{k:"grund", q:"Hvad betyder ansvarsgrundlag?",
 o:["Den regel der afgør, hvornår nogen skal betale erstatning","Det højeste beløb, transportøren skal betale","Den frist, man har for at klage","Det dokument, der følger med godset"],
 f:"Ansvarsgrundlaget er svaret på spørgsmålet: Kan vi kræve erstatning? Man kan ikke bare kræve penge. Der skal være en regel, der siger, at modparten skal betale. Hver transportform har sit eget ansvarsgrundlag. Det højeste beløb hedder ansvarsbegrænsning eller loft. Fristen hedder reklamation. Dokumentet hedder fragtbrev eller konnossement.",
 p:"SL § 275, CMR § 24, LFL §§ 108-109, NSAB § 15."},
{k:"grund", q:"Hvilke fire betingelser skal være opfyldt for at få erstatning?",
 o:["Økonomisk tab, ansvarsgrundlag, årsagssammenhæng og adækvans","Kontrakt, fragtbrev, forsikring og betaling","Skyld, vidner, politianmeldelse og dom","Tab, reklamation, forældelse og Incoterm"],
 f:"For at få erstatning skal der være 1) et økonomisk tab, 2) et ansvarsgrundlag, 3) årsagssammenhæng, altså at tabet skyldes handlingen, og 4) adækvans, altså at tabet kunne forudses. Mangler én af dem, får man ingen erstatning. I GPE-opgaven blev kammer 3 sejlet på dæk i strid med aftalen, men det blev ikke skadet. Så var der intet tab og ingen erstatning.",
 p:"Almindelige erstatningsregler. CJ lektion 3."},
{k:"grund", q:"Hvad betyder culpa?",
 o:["Skyld, altså at man har været uagtsom eller handlet med vilje","Ansvar uden skyld","En international konvention","Et loft over erstatningen"],
 f:"Culpa er latin og betyder skyld. Man har culpa, når man har været uagtsom eller har gjort noget med vilje. Man spørger: Ville en fornuftig og forsigtig person have gjort det samme? Hvis nej, er der culpa. Culpa er den almindelige regel i dansk ret uden for transport. Ansvar uden skyld hedder objektivt ansvar.",
 p:"Culpareglen er lavet af domstolene, ikke en paragraf."},
{k:"grund", q:"Hvad er objektivt ansvar?",
 o:["Man skal betale, selv om man ikke har gjort noget forkert","Man skal kun betale, hvis man har været uagtsom","Kunden skal bevise transportørens skyld","Man skal kun betale ved forsæt"],
 f:"Objektivt ansvar er ansvar uden skyld. Det er det strengeste ansvar. CJ's huskeregel: Står der ikke et eneste ord om culpa, uagtsomhed eller fejl i reglen, så er det objektivt ansvar. CMR § 24 og NSAB § 15 siger bare, at transportøren er ansvarlig fra han får godset, til han afleverer det. Derfor er det objektivt ansvar.",
 p:"CMR § 24, NSAB § 15, LFL § 108, CISG art. 74, KBL § 24."},
{k:"grund", q:"Hvad betyder culpa med omvendt bevisbyrde?",
 o:["Man formoder, at transportøren har skyld, og han skal selv bevise, at han ikke har","Kunden skal bevise, at transportøren har skyld","Transportøren betaler altid, uanset hvad han beviser","Ingen skal bevise noget"],
 f:"Normalt skal den, der vil have erstatning, bevise skylden. Ved omvendt bevisbyrde er det vendt om. Loven går ud fra, at transportøren har skyld. Kan han ikke bevise det modsatte, skal han betale. Det kaldes også formodningsansvar eller præsumptionsansvar. CJ siger, at bevisbyrden er streng, men at det ikke er det samme som objektivt ansvar, fordi transportøren kan slippe ved at bevise, at han ikke lavede fejl.",
 p:"SL § 275, LFL § 109, KBL § 23."},
{k:"grund", q:"Hvordan kan man se, at en regel giver objektivt ansvar?",
 o:["Der står ikke noget om culpa, uagtsomhed eller fejl i reglen","Reglen står i søloven","Reglen nævner SDR","Reglen har mange stykker"],
 f:"CJ brugte CISG art. 74 som eksempel. Han spurgte: Hvordan fandt vi ud af, at det er objektivt ansvar? Svaret var, at der ikke står et eneste ord om culpa, uagtsomhed eller negligence i bestemmelsen. Det samme gælder CMR § 24 og NSAB § 15. Søloven § 275 nævner derimod 'fejl eller forsømmelse', og derfor er det culpa med omvendt bevisbyrde.",
 p:"CISG art. 74 (CJ lektion 1)."},
{k:"grund", q:"Hvad er forskellen på uagtsomhed og grov uagtsomhed?",
 o:["Grov uagtsomhed er meget skødesløst, hvor helt elementære regler er tilsidesat","Der er ingen forskel","Grov uagtsomhed betyder, at man gjorde det med vilje","Uagtsomhed er værre end grov uagtsomhed"],
 f:"Uagtsomhed er at være skødesløs. Grov uagtsomhed er at være meget skødesløs, hvor man har tilsidesat helt elementære regler. At gøre det med vilje hedder forsæt. Forskellen er vigtig, fordi grov uagtsomhed og forsæt giver gennembrud til fuld erstatning. Almindelig uagtsomhed giver ikke gennembrud.",
 p:"CMR § 37, NSAB § 6 stk. 2, SL § 283."},
{k:"grund", q:"Hvad betyder gennembrud til fuld erstatning?",
 o:["Loftet over erstatningen gælder ikke, og kunden får hele sit tab","Transportøren slipper helt for at betale","Kunden får dobbelt erstatning","Sagen skal for Højesteret"],
 f:"Normalt har transportøren et loft over erstatningen, fx 8,33 SDR pr. kg. Ved gennembrud gælder loftet ikke. Så skal transportøren betale hele tabet efter almindelige erstatningsregler. Det kræver forsæt eller grov uagtsomhed. Kunden har bevisbyrden, og det er tit svært at bevise. For gods med fly findes der slet ikke gennembrud.",
 p:"CMR § 37, NSAB § 6 stk. 2, SL §§ 283-284, CIM art. 36."},
{k:"grund", q:"Hvem skal bevise grov uagtsomhed, når kunden vil have gennembrud?",
 o:["Kunden (den skadelidte)","Transportøren","Forsikringsselskabet","Ingen, retten afgør det selv"],
 f:"Det er kunden, der vil have mere end loftet. Derfor er det kunden, der skal bevise forsæt eller grov uagtsomhed. Det kaldes ligefrem bevisbyrde. NSAB § 6 stk. 3 siger desuden, at det ikke i sig selv er grov uagtsomhed, at man ikke kan finde ud af, hvordan godset blev skadet. Derfor ender kunden tit med kun at få loftet.",
 p:"NSAB § 6 stk. 3. CJ: 'Altid ligefrem bevisbyrde' ved gennembrud."},
{k:"grund", q:"Hvad er 'det hændelige'?",
 o:["Et uheld, hvor ingen har skylden","En skade, transportøren har lavet med vilje","En forsinkelse på over 60 dage","En aftale om dækslast"],
 f:"Det hændelige er et uheld uden skyldig. Nogen taber penge, men der er ingen at give skylden. Så afgør køberetten, hvem der bærer tabet. Det afhænger af, om risikoen er gået over fra sælger til køber. I Jack & Jeans væltede lastbilen, og 20 par jeans faldt i en branddam med gylle. Ingen havde skyld.",
 p:"KBL § 17."},
{k:"grund", q:"Hvad er SDR?",
 o:["En regne-valuta fra Den Internationale Valutafond, som lovene bruger til lofter","En dansk afgift på transport","Et fragtbrev til tog","En forsikring mod tyveri"],
 f:"SDR står for Special Drawing Rights. Det er en regne-valuta fra Den Internationale Valutafond. Lovene bruger SDR, fordi den er den samme i alle lande. Man ganger vægten i kg med SDR-satsen og derefter med kursen i kroner. I CJ's opgaver er kursen cirka 9,15-9,32 kr. CMR § 29 stk. 2 siger, at man bruger kursen den dag, dommen falder, eller en dag parterne aftaler.",
 p:"CMR § 29 stk. 2, SL § 280."},
{k:"grund", q:"Hvad er regres?",
 o:["At den, der har betalt erstatning, kræver pengene tilbage hos den, der lavede skaden","At kunden trækker sit krav tilbage","At sagen sendes til en anden domstol","At godset sendes tilbage til sælger"],
 f:"Kunden kræver den kontraherende transportør, fordi kunden har aftalen med ham. Han betaler. Bagefter kræver han pengene tilbage hos undertransportøren, der faktisk lavede fejlen. Det hedder regres. I Helt i fisk betaler Big Whale Shipping kunden og kræver derefter pengene hos GT Transport, som samlæssede medicinen med fisk.",
 p:"SL § 287 stk. 3, CMR § 46."},
{k:"grund", q:"Hvad dækker transportlovenes erstatning normalt IKKE?",
 o:["Tabt fortjeneste og driftstab","Godsets værdi","Fragt og told","Værdiforringelse ved skade"],
 f:"Transportlovene giver normalerstatning. Man får godsets almindelige værdi plus fragt, told og omkostninger. Man får ikke sit konkrete tab som tabt fortjeneste, driftstab eller mistet markedsandel. I Muuh-opgaven ville kunden have tabt arbejdsfortjeneste, fordi gravkoen ikke virkede. Det dækker CMR næppe.",
 p:"CMR § 29, NSAB § 17 (ingen tabt avance), SL § 279."},
{k:"grund", q:"Hvordan kan afsender få et højere loft end lovens?",
 o:["Ved at angive en højere værdi eller en særlig interesse mod et tillæg til fragten","Ved at skrive en klage bagefter","Ved at vælge et dyrere skib","Det kan man aldrig"],
 f:"Er godset meget værdifuldt i forhold til vægten, kan afsender betale et tillæg til fragten. Så skriver man en højere værdi eller en særlig interesse i fragtbrevet. Loftet stiger til det beløb. I Helt i fisk vejede medicin for ca. 660.000 kr. kun 163 kg. Uden angiven værdi gav loftet kun ca. 12.560 kr.",
 p:"CMR §§ 30 og 33, NSAB § 21 litra D, LFL § 111 stk. 5, CIM art. 34-35."},

// ===================== AFTALER OG NSAB =====================
{k:"nsab", q:"Hvad er et 'agreed document'?",
 o:["En standardaftale, som begge sider har forhandlet, fx NSAB 2015","En lov vedtaget af Folketinget","En dom fra Højesteret","Et fragtbrev underskrevet af chaufføren"],
 f:"Et agreed document er en standardaftale, som både speditørerne og kunderne har forhandlet. Derfor anses vilkårene for at være fair. Det er ikke en lov, men det gælder, når parterne har aftalt det. NSAB 2015 er forhandlet mellem Nordisk Speditørforbund og erhvervsorganisationer som Dansk Erhverv.",
 p:"NSAB 2015, indledningen."},
{k:"nsab", q:"Hvornår gælder NSAB 2015?",
 o:["Når speditøren er medlem af Nordisk Speditørforbund (Danske Speditører), og NSAB er aftalt","Altid ved transport i Danmark","Kun ved skibstransport","Kun hvis kunden er en privatperson"],
 f:"NSAB § 1 siger, at bestemmelserne gælder for medlemmer af Nordisk Speditørforbund. I Danmark er det Danske Speditører. NSAB skal også være aftalt i det konkrete forhold, fx ved at speditøren henviser til NSAB. I Furs & Feathers henviste Blue Water til NSAB i sin mailsignatur.",
 p:"NSAB § 1."},
{k:"nsab", q:"Hvad siger netværksreglen i NSAB § 2?",
 o:["Er en transportform aftalt, eller kan man bevise, hvor skaden skete, bruges loven for den transportform","NSAB gælder altid i stedet for lovene","Kunden må selv vælge den lov, der giver mest","Speditøren slipper, hvis der er flere transportformer"],
 f:"NSAB § 2 er netværksreglen. Har man aftalt en bestemt transportform, eller kan det bevises, hvor skaden skete, er speditøren ansvarlig efter loven for den transportform. CJ siger: NSAB sender os hjem. I Papaya skete skaden i havnen hos rederiet. Derfor sendte NSAB sagen over til søloven. Kan man ikke se, hvor det gik galt, bliver man i NSAB.",
 p:"NSAB § 2."},
{k:"nsab", q:"Hvad gør man, hvis man ikke ved, på hvilken transportform skaden skete?",
 o:["Man bruger NSAB's egne regler, §§ 15-21","Man bruger altid søloven","Kunden får ingen erstatning","Man bruger den lov med det laveste loft"],
 f:"Netværksreglen kræver, at man ved, hvor skaden skete, eller at en transportform er aftalt. Ved man ikke det, bliver man i NSAB og bruger § 6 og §§ 15-21. Det betyder objektivt ansvar med fritagelser og et loft på 8,33 SDR pr. kg. I Furs & Feathers regnede CJ sådan: 14,5 kg x 8,33 x 9,32 = 1.125,72 kr.",
 p:"NSAB §§ 15-21."},
{k:"nsab", q:"Hvad er ansvarsgrundlaget i NSAB § 15?",
 o:["Objektivt ansvar med fritagelser","Almindelig culpa","Culpa med omvendt bevisbyrde","Intet ansvar"],
 f:"NSAB § 15 siger, at speditøren er ansvarlig for bortkomst, forringelse og skade fra han overtager godset, til han afleverer det, og for forsinkelse. Der står intet om culpa. Derfor er det objektivt ansvar. CJ sagde det direkte i gulerod-opgaven. Speditøren kan kun slippe, hvis en af fritagelserne i § 16 passer.",
 p:"NSAB §§ 15-16."},
{k:"nsab", q:"Hvad er loftet for skade på gods efter NSAB?",
 o:["8,33 SDR pr. kg","2 SDR pr. kg","26 SDR pr. kg","17 SDR pr. kg"],
 f:"NSAB § 21 litra A siger, at speditørens ansvar for bortkomst, forringelse eller skade er begrænset til 8,33 SDR pr. kg bruttovægt af den del, der er skadet. Det er det samme som CMR. Ved forsinkelse er loftet fragtbeløbet. For alle andre tab er loftet 100.000 SDR pr. opgave.",
 p:"NSAB § 21."},
{k:"nsab", q:"Hvornår er der gennembrud efter NSAB § 6 stk. 2?",
 o:["Ved speditørens eller hans ansattes forsæt eller grove uagtsomhed, eller undertransportørens forsæt","Ved enhver fejl fra speditøren","Kun ved undertransportørens grove uagtsomhed","Aldrig"],
 f:"NSAB § 6 stk. 2 skelner mellem to grupper. For speditøren selv og hans egne ansatte er det nok med forsæt ELLER grov uagtsomhed. For medkontrahenter, altså undertransportører, kræves forsæt. CJ understregede det i gulerod-opgaven: Det er ikke nok, at undertransportøren har handlet groft uagtsomt.",
 p:"NSAB § 6 stk. 2."},
{k:"nsab", q:"PH Thomsens eksterne vognmand var groft uagtsom, da gulerødderne væltede. Er der gennembrud efter NSAB?",
 o:["Nej, for undertransportøren kræves forsæt","Ja, grov uagtsomhed er altid nok","Ja, fordi det skete i Danmark","Nej, fordi NSAB slet ikke har gennembrud"],
 f:"Vognmanden er undertransportør (medkontrahent) for PH Thomsen. Efter NSAB § 6 stk. 2 kræver gennembrud forsæt hos medkontrahenten. Grov uagtsomhed er ikke nok. Gennembrud ville kun kunne ske ved PH Thomsens egen eller egne ansattes grove uagtsomhed. CJ skrev: 'Gennembrud til fuld erstatning kunne jeg næppe komme igennem med i denne sag!'",
 p:"NSAB § 6 stk. 2. CJ's løsning i lektion 5."},
{k:"nsab", q:"Hvem læsser, og hvem stuver og sikrer godset efter NSAB?",
 o:["Ordregiveren læsser og losser, speditøren stuver og sikrer","Speditøren gør det hele","Ordregiveren gør det hele","Modtageren læsser"],
 f:"NSAB § 5 siger, at medmindre andet er aftalt, skal ordregiveren sørge for læsning og losning, mens speditøren skal sørge for stuvning og sikring af godset. Det er vigtigt i surrings-sager. Er godset dårligt surret, er det som udgangspunkt speditørens problem efter NSAB.",
 p:"NSAB § 5."},
{k:"nsab", q:"Hvad er forskellen på en kontraherende speditør og en formidler?",
 o:["Den kontraherende er ansvarlig som transportør, formidleren kun for omhu og egne ansatte","Der er ingen forskel","Formidleren er ansvarlig for alle undertransportører","Den kontraherende er kun rådgiver"],
 f:"En kontraherende speditør (NSAB § 3B) laver aftalen i eget navn og er ansvarlig for hele transporten, også for de undertransportører, han hyrer. En formidler (§ 3C) handler ikke i eget navn eller for egen regning og skal have sagt det tydeligt til kunden. Formidleren er kun ansvarlig for egne ansatte og for at vise omhu, fx ved valget af transportør (§ 22). Loftet er højst 50.000 SDR pr. opgave (§ 24).",
 p:"NSAB §§ 3B, 3C, 22 og 24."},
{k:"nsab", q:"Hvilken af disse er IKKE en fritagelse i NSAB § 16?",
 o:["At chaufføren kørte for stærkt","Ordregiverens egen fejl","Manglende eller dårlig emballage","Forhold speditøren ikke kunne undgå"],
 f:"NSAB § 16 har listen litra a-h: ordregiverens fejl, ordregiverens læsning eller stuvning, godsets letskadelige beskaffenhed, manglende emballage, fejl i mærkning, forkerte oplysninger, åbne transportmidler når det er sædvanligt eller aftalt, og forhold speditøren ikke kunne undgå. At chaufføren kører for stærkt er speditørens egen side, så det fritager ikke. Det kan tværtimod tale for grov uagtsomhed.",
 p:"NSAB § 16."},
{k:"nsab", q:"Hvordan beregnes erstatning for tabt gods efter NSAB § 17?",
 o:["Efter fakturaværdien, plus fragt, told og udlæg, men uden tabt avance","Efter salgsprisen hos køberen inkl. fortjeneste","Efter hvad kunden selv mener","Altid 100.000 SDR"],
 f:"NSAB § 17 siger, at erstatningen beregnes efter godsets fakturaværdi, medmindre markedsprisen var en anden ved overtagelsen. Dertil kommer fragt, told og andre udlæg. Speditøren betaler ikke for tabt avance, mistet markedsandel eller andre tab. Loftet er stadig 8,33 SDR pr. kg efter § 21.",
 p:"NSAB §§ 17 og 21."},
{k:"nsab", q:"Hvad gælder for lager efter NSAB?",
 o:["Speditøren skal forsikre godset, og ud over forsikringen hæfter han for fejl","Lager er ikke dækket af NSAB","CMR gælder for lager","Speditøren har aldrig ansvar for lager"],
 f:"NSAB § 25 handler om oplagring. Speditøren skal tegne forsikring for brand, vand og indbrud baseret på fakturaværdien plus 10 procent. For skader uden for forsikringen hæfter han for fejl eller forsømmelser efter §§ 17-18 og 21. Højst 500.000 SDR pr. hændelse. Lovene som CMR og søloven har ingen regler om lager. Derfor er NSAB vigtig her.",
 p:"NSAB §§ 3D og 25."},
{k:"nsab", q:"Hvornår skal man reklamere efter NSAB ved skjult skade?",
 o:["Inden 7 kalenderdage fra levering","Inden 3 dage","Inden 21 dage","Inden 1 år"],
 f:"NSAB § 27 siger: Synlig skade skal reklameres straks ved modtagelsen. Skjult skade senest 7 kalenderdage fra leveringen. Andre krav, fx forsinkelse, inden 14 dage. Reklamerer man ikke til tiden over en skade, skal ordregiveren bevise, at skaden skete hos speditøren. Ved andre krav mister man retten.",
 p:"NSAB § 27."},
{k:"nsab", q:"Hvad er forældelsesfristen efter NSAB?",
 o:["1 år","2 år","3 år","6 måneder"],
 f:"NSAB § 28 siger, at sag mod speditøren skal anlægges inden et år. Ellers er kravet tabt. Fristen løber fx fra den dag, godset blev leveret, ved skade. Bemærk at netværksreglen også gælder her: skete skaden fx på en lastbil mellem lande, gælder CMR's regler.",
 p:"NSAB § 28."},
{k:"nsab", q:"Er en henvisning til NSAB i en mailsignatur nok til, at NSAB gælder?",
 o:["Formentlig ja mellem professionelle, men man bør nævne argumentet imod","Nej, aldrig","Ja, altid uden diskussion","Kun hvis kunden har underskrevet NSAB"],
 f:"Mellem to professionelle parter taler meget for, at NSAB er vedtaget, fordi NSAB er helt sædvanligt i branchen. Argumentet imod er, at en henvisning i en signatur er diskret og ensidig, og at ansvarsbegrænsninger kræver tydelig accept. Til eksamen skal du nævne begge sider og så konkludere, som i Furs & Feathers.",
 p:"NSAB § 1. Almindelig aftaleret."},

// ===================== PARTER =====================
{k:"parter", q:"Hvem skal kunden rette sit erstatningskrav mod?",
 o:["Den kontraherende transportør eller speditør, som kunden har aftalen med","Chaufføren personligt","Den undertransportør, der lavede skaden","Forsikringsselskabet"],
 f:"Kunden har sin aftale med den kontraherende transportør eller speditør. Han hæfter for hele transporten, også for sine undertransportører. Derfor retter kunden kravet mod ham. Bagefter kan han tage regres hos undertransportøren. I Papaya rettede Maxi-Grossisten kravet mod TotalTransport, ikke mod rederiet CMA-CGM.",
 p:"SL § 285, CMR § 4, NSAB § 3B."},
{k:"parter", q:"Hvad er forskellen på en afsender og en aflaster i søloven?",
 o:["Afsenderen har aftalen med transportøren, aflasteren afleverer godset fysisk","Det er det samme","Aflasteren modtager godset i lossehavnen","Afsenderen er altid køberen"],
 f:"Søloven § 251 definerer begge. Afsender er den, der laver aftale med transportøren om transporten. Aflaster er den, der fysisk leverer godset til transporten. Det kan være to forskellige. Ved et FOB-køb bestiller køberen skibet og er afsender, men sælgeren afleverer godset i havnen og er aflaster.",
 p:"SL § 251 nr. 3 og 4."},
{k:"parter", q:"Hvad er en undertransportør?",
 o:["Den, der efter aftale med transportøren udfører hele eller en del af transporten","Den, der køber transporten","Den, der modtager godset","En speditør, der kun rådgiver"],
 f:"Undertransportøren er hyret af den kontraherende transportør. Han kører, sejler eller flyver faktisk godset. Kunden har ingen aftale med ham. I NSAB hedder han medkontrahent. I GPE hyrede Holst Transport en undertransportør til turen fra Bremerhaven til Barcelona.",
 p:"SL § 251 nr. 2."},
{k:"parter", q:"Hvem hæfter fragtføreren for efter CMR § 4?",
 o:["Sine ansatte og alle andre, han bruger til transporten","Kun sig selv","Kun chauffører, han selv har ansat","Kun afsenderen"],
 f:"CMR § 4 siger, at fragtføreren er ansvarlig for handlinger og undladelser fra sine ansatte og alle andre, han bruger til transporten, som var det hans egne. Det omfatter undertransportører. Derfor hæftede DSV for tyveriet hos sin tjekkiske undertransportør JS Euroline.",
 p:"CMR § 4."},
{k:"parter", q:"Hvad sker der, hvis både transportøren og undertransportøren er ansvarlige efter søloven?",
 o:["De hæfter solidarisk","Kun undertransportøren betaler","Kun transportøren betaler","De deler altid 50-50 over for kunden"],
 f:"Søloven § 287 siger, at de hæfter solidarisk. Det betyder, at kunden kan kræve hele beløbet af hvem af dem, han vil. Det samlede ansvar kan dog ikke overstige loftet i § 280, medmindre der er gennembrud. Bagefter kan de afregne indbyrdes ved regres.",
 p:"SL § 287."},

// ===================== TRANSPORTFORMER =====================
{k:"former", q:"Hvilken lov gælder for lastbiltransport fra Hamborg til Aalborg?",
 o:["CMR-loven","Søloven","Luftfartsloven","Købeloven"],
 f:"CMR-loven gælder for aftaler om vejtransport af gods med køretøj mod betaling mellem forskellige lande. Hamborg-Aalborg går fra Tyskland til Danmark, så CMR gælder. Det er Vaskeri-opgaven. Selv om Global Forwarding brugte NSAB, sender NSAB § 2 sagen til CMR, fordi skaden skete på lastbilen.",
 p:"CMR § 1, NSAB § 2."},
{k:"former", q:"Hvilke regler bruger man ved lastbiltransport fra Års til Padborg?",
 o:["Aftalen, typisk NSAB, fordi CMR kun gælder mellem lande","CMR-loven","Søloven","Luftfartsloven"],
 f:"Års-Padborg er en transport inden for Danmark. CMR gælder kun international vejtransport. Danmark har ingen lov om national lastbilkørsel. Derfor er der aftalefrihed, og man bruger aftalen. I PH Thomsen-opgaven brugte CJ NSAB 2015 som agreed document.",
 p:"CMR § 1 (kun international). CJ's gulerod-løsning."},
{k:"former", q:"Hvad er forskellen på multimodal og intermodal transport?",
 o:["Multimodal er én aftale med flere transportformer, intermodal er separate aftaler","Multimodal er kun skib, intermodal kun lastbil","Der er ingen forskel","Intermodal er altid billigere"],
 f:"Ved multimodal transport har kunden én aftale med én transportør eller speditør, som bruger flere transportformer. Der er én ansvarlig. Ved intermodal transport laver kunden selv separate aftaler med hver transportør. Så er hver kun ansvarlig for sin del. Furs & Feathers er multimodal: Blue Water havde både fly og lastbil i én aftale.",
 p:"CJ lektion 5."},
{k:"former", q:"Gælder CMR, hvis godset skades i Danmark på en tur, der skal ende i Tyskland?",
 o:["Ja, det afgørende er, hvad aftalen siger om afsendelses- og bestemmelsessted","Nej, kun hvis skaden sker i udlandet","Nej, så gælder søloven","Kun hvis chaufføren er tysk"],
 f:"CMR gælder, når fragtaftalen går fra ét land til et andet. Det afgørende er afsendelses- og bestemmelsesstedet i aftalen, ikke hvor skaden sker. En tur fra Danmark til Tyskland er international fra starten. Karnov-noten nævner U 2001 1269 H, hvor CMR gjaldt, selv om godset blev skadet, før det forlod Danmark.",
 p:"CMR § 1, Karnov-note 5."},
{k:"former", q:"Hvad er piggyback-reglen i CMR § 3?",
 o:["Kører lastbilen med godset om bord på et skib eller tog uden at blive aflæsset, gælder CMR hele vejen","Godset må ikke læsses om","Chaufføren må tage en passager med","Man må bruge to lastbiler"],
 f:"CMR § 3 siger, at hvis lastbilen med godset sejles med skib eller køres med tog, uden at godset aflæsses, gælder CMR for hele transporten. Der er en undtagelse: Skyldes skaden noget, der kun kunne ske på skibet eller toget, bruges loven for den transportform. Eksempel: en lastbil på færgen fra Esbjerg til Harwich.",
 p:"CMR § 3."},
{k:"former", q:"Gælder søloven kapitel 13, når man lejer et helt skib (certeparti)?",
 o:["Nej, kapitel 13 gælder stykgods, ikke certepartier","Ja, altid","Kun hvis skibet er dansk","Kun ved dækslast"],
 f:"Søloven § 253 siger, at kapitel 13 ikke gælder for certepartier for hel- eller delbefragtning af skib. Når man lejer hele eller dele af et skib, hedder det befragtning, og reglerne står i kapitel 14. Kapitel 13 gælder stykgods, altså enkelte forsendelser som containere.",
 p:"SL § 253."},

// ===================== SØLOVEN =====================
{k:"so", q:"Hvad er ansvarsgrundlaget i søloven § 275?",
 o:["Culpa med omvendt bevisbyrde","Objektivt ansvar","Almindelig culpa","Intet ansvar"],
 f:"Søloven § 275 siger, at transportøren er ansvarlig for tab, når godset skades eller går tabt, mens han har det, medmindre han godtgør, at fejl eller forsømmelse fra ham selv eller nogen, han svarer for, ikke har forårsaget tabet. Fordi reglen nævner 'fejl eller forsømmelse', er det culpa. Fordi transportøren skal bevise sin uskyld, er bevisbyrden omvendt. Det kaldes også præsumptionsansvar.",
 p:"SL § 275."},
{k:"so", q:"Hvornår har søtransportøren godset i sin varetægt?",
 o:["I lastehavnen, under sejladsen og i lossehavnen","Kun mens godset er om bord","Kun under selve sejladsen","Fra sælgers lager til købers lager"],
 f:"Søloven § 274 siger, at transportøren er ansvarlig, mens godset er i hans varetægt i lastehavnen, under transporten og i lossehavnen. Det starter, når han modtager godset, og slutter, når han udleverer det. Derfor var tiden i havnen i Dunkerque med i Papaya. En klausul om, at han kun hæfter fra kran til kran ('tackle to tackle'), er ugyldig.",
 p:"SL § 274, Karnov-note (U 2011.271 H)."},
{k:"so", q:"Hvad er loftet over erstatning efter søloven?",
 o:["Det højeste af 667 SDR pr. kollo eller 2 SDR pr. kg","8,33 SDR pr. kg","26 SDR pr. kg","Altid fragtbeløbet"],
 f:"Søloven § 280 siger, at transportørens ansvar ikke skal overstige 667 SDR pr. kollo eller 2 SDR pr. kg bruttovægt, afhængigt af hvad der giver det højeste beløb. Man skal altså regne begge og vælge det, der er bedst for kunden. Ved forsinkelse er loftet 2,5 gange fragten for det forsinkede gods, højst hele fragten.",
 p:"SL § 280."},
{k:"so", q:"I Papaya-opgaven vejede den beskadigede frugt 8.940 kg. B/L nævnte ca. 117 kasser. Hvilket loft er bedst for kunden? (kurs 9,25)",
 o:["117 kolli x 667 SDR = ca. 719.666 kr.","8.940 kg x 2 SDR = ca. 165.390 kr.","8.940 kg x 8,33 SDR","10 paller x 667 SDR"],
 f:"Regn begge: Efter vægt: 8.940 x 2 x 9,25 = 165.390 kr. Efter kolli: 117 x 667 x 9,25 = 719.666 kr. Søloven § 280 siger, at det højeste gælder. Tabet var 348.660 kr. Står kasserne i B/L, er hele tabet dækket. Står der kun 10 paller, tæller pallerne som kolli (§ 281), og så giver vægten mest. Derfor er det vigtigt, hvad der står i B/L.",
 p:"SL §§ 280-281. CJ's vejledende besvarelse."},
{k:"so", q:"Hvad siger containerklausulen i søloven § 281?",
 o:["Står kasserne i containeren skrevet i transportdokumentet, tæller hver kasse som et kollo","En container tæller altid som 10 kolli","Containere er aldrig omfattet af loven","Containeren må ikke sejles på dæk"],
 f:"Søloven § 281 siger, at bruger man container eller paller, tæller hvert kollo, der er nævnt i transportdokumentet som pakket i containeren, som et kollo. Står det ikke, tæller indholdet som én enhed. Selve containeren er en særskilt enhed, hvis transportøren ikke ejer den.",
 p:"SL § 281."},
{k:"so", q:"I dommen Topdanmark mod DSV (BS-36988/2022) stod der både '5 pallet(s)' og '5PLT=108CTNS' i B/L. Hvad gjorde retten?",
 o:["Brugte 108 kolli, fordi uklarheden gik ud over DSV, der havde skrevet B/L","Brugte 5 kolli, fordi paller står først","Afviste sagen","Brugte vægten i stedet"],
 f:"Retten så på B/L sammen med pakkelisten og fakturaen. De viste 108 kartoner. Retten sagde, at aftalen gjaldt 108 kartoner. Det havde været mest korrekt at skrive 108 under antal kolli, men uklarheden skulle gå ud over DSV, der havde skrevet konnossementet. Det kaldes koncipist-reglen. Loftet blev beregnet på 108 kolli, og DSV skulle betale fakturaværdien 235.125 kr.",
 p:"SL §§ 280-281. Sø- og Handelsretten 21. april 2023."},
{k:"so", q:"Hvad er en nautisk fejl?",
 o:["En fejl i navigationen eller i behandlingen af skibet","En fejl i behandlingen af lasten","En forsinkelse på over 60 dage","En fejl i konnossementet"],
 f:"Søloven § 276 stk. 1 nr. 1 siger, at transportøren ikke er ansvarlig for fejl i navigeringen eller behandlingen af skibet, begået af skibsfører, mandskab eller lods. Men fejl i behandlingen af lasten fritager ikke. Grænsen er svær. Pumpede man vand ind i lasten for at stabilisere skibet, blev rederiet frifundet. En kølecontainer uden strøm er derimod fejl med lasten.",
 p:"SL § 276. CJ's slides om norske domme."},
{k:"so", q:"I Ost til Portugal var containeren ikke sat til strøm om bord. Kan transportøren påberåbe sig nautisk fejl?",
 o:["Nej, strøm til en kølecontainer er behandling af lasten","Ja, alt der sker om bord er nautisk","Ja, fordi besætningen lavede fejlen","Nej, fordi det skete i havnen"],
 f:"Nautisk fejl dækker kun fejl med navigationen eller med skibet. At sætte strømstikket ordentligt i en reefer-container handler om at passe på lasten. Derfor fritager det ikke. Transportøren er ansvarlig efter § 275, fordi han ikke kan bevise, at der ikke var fejl. Osten var totalskadet.",
 p:"SL §§ 275-276."},
{k:"so", q:"Hvilke fritagelser findes i søloven?",
 o:["Redning af mennesker og bjærgning, nautiske fejl og brand, og særlige risici ved levende dyr","Kun force majeure","Alle skader under hårdt vejr","Fejl i behandlingen af lasten"],
 f:"Søloven har tre grupper af fritagelser. § 275 stk. 2: tab ved redning af mennesker eller rimelig bjærgning af skib eller ejendom til søs. § 276: nautiske fejl og brand, medmindre branden skyldes transportøren selv. § 277: særlige risici ved transport af levende dyr. Hårdt vejr fritager kun, hvis transportøren kan bevise, at han ikke lavede fejl.",
 p:"SL §§ 275 stk. 2, 276 og 277."},
{k:"so", q:"Hvad betyder sødygtighed?",
 o:["At skibet er bemandet og udrustet, og at lastrum og kølerum er i orden","At skibet kan sejle hurtigt","At skibet er forsikret","At skibet har en dansk kaptajn"],
 f:"Søloven § 262 stk. 2 siger, at transportøren skal sørge for, at skibet er sødygtigt. Det betyder tilstrækkelig besætning og udrustning, og at lastrum, køle- og fryserum er i god stand til godset. Det kaldes også lastedygtighed. Efter § 276 stk. 2 hæfter transportøren for usødygtighed ved rejsens begyndelse, hvis han ikke har vist tilbørlig omhu.",
 p:"SL §§ 262 stk. 2 og 276 stk. 2."},
{k:"so", q:"Får til Dublin: Vandingssystemet om bord svigter, og fårene dør. Kan transportøren uden videre bruge fritagelsen for levende dyr i § 277?",
 o:["Næppe, fordi et vandingssystem, der svigter, peger på manglende sødygtighed","Ja, dyr er altid transportørens fritagelse","Ja, fordi afsender gav instrukser","Nej, fordi får ikke er gods"],
 f:"§ 277 fritager kun for de særlige risici ved dyretransport, og transportøren skal vise, at han har fulgt instrukserne. Men et vandingssystem er skibets udstyr. Svigter det, peger det på, at skibet ikke var i orden (§ 262 stk. 2 og § 276 stk. 2). Så er hovedreglen i § 275 tilbage: transportøren skal bevise, at der ikke var fejl. Det bliver svært.",
 p:"SL §§ 262, 275, 276 stk. 2 og 277. Løsningsforslag."},
{k:"so", q:"Hvornår kan forsinkelse behandles som tab af godset efter søloven?",
 o:["Når godset ikke er udleveret inden 60 dage efter, det skulle have været det","Efter 30 dage","Efter 21 dage","Efter 7 dage"],
 f:"Søloven § 278 stk. 3 siger, at er godset ikke udleveret inden 60 dage fra den dag, det skulle have været udleveret, kan der kræves erstatning som for tab. I Skælskør-opgaven stod container 1 glemt på havnen i 62 dage. Så kan kunden kræve erstatning, som om godset var væk. Det giver mere end forsinkelses-loftet på 2,5 gange fragten.",
 p:"SL § 278 stk. 3."},
{k:"so", q:"Hvornår er der gennembrud efter søloven § 283?",
 o:["Når transportøren selv har handlet forsætligt eller groft uagtsomt og vidste, at tabet sandsynligvis ville ske","Når en sømand laver en fejl","Når godset er forsinket","Når der ikke er taget forbehold"],
 f:"§ 283 siger, at den ansvarlige ikke kan begrænse sit ansvar, hvis han selv har forvoldt tabet forsætligt eller groft uagtsomt og med forståelse af, at tabet sandsynligvis ville ske. Ordet 'selv' er vigtigt. Ifølge Karnov tæller transportøren og overordnede ledere, men næppe skibsføreren og ikke almindelige sømænd. Søloven har ikke CMR's regel om, at medhjælperes grove uagtsomhed tæller.",
 p:"SL § 283. Karnov-note 605."},
{k:"so", q:"GPE: En sømand smider med vilje et tørrekammer over bord. CJ siger gennembrud. Hvad er den kritiske pointe?",
 o:["§ 283 kræver, at transportøren 'selv' har handlet, og en almindelig sømand tæller næppe","Der er ingen kritisk pointe","Søloven har slet ikke gennembrud","Det er en nautisk fejl"],
 f:"CJ's løsning er, at kammeret blev smidt over bord med vilje, og at der derfor er gennembrud. Men læs § 283 nøje: den kræver, at den ansvarlige 'selv' har handlet. Karnov siger, at det næppe omfatter skibsføreren og slet ikke almindelige sømænd. Til eksamen er det stærkt at nævne CJ's resultat og så denne kritiske pointe. Loftet var i forvejen ca. 180.000 kr. (10.000 kg x 2 SDR), næsten kammerets værdi på 200.000 kr.",
 p:"SL § 283. CJ's GPE-bemærkninger."},
{k:"so", q:"Hvornår må gods sejles på dæk?",
 o:["Kun hvis det er aftalt, er sædvane eller kræves af lov","Altid, hvis der er plads","Aldrig","Kun ved containere"],
 f:"Søloven § 263 siger, at gods kun må transporteres på dæk, hvis det er tilladt i aftalen, følger af handelsbrug eller sædvane, eller kræves af lov. Er det aftalt, skal det stå i transportdokumentet. Ellers skal transportøren bevise aftalen. Sejles godset ulovligt på dæk, hæfter transportøren for skader fra dæktransporten (§ 284).",
 p:"SL §§ 263 og 284."},
{k:"so", q:"Gods sejles på dæk, selv om der var en udtrykkelig aftale om under dæk. Hvad er følgen?",
 o:["Transportøren mister retten til ansvarsbegrænsning","Transportøren slipper for ansvar","Kunden mister sit krav","Der sker intet"],
 f:"Søloven § 284 stk. 2 siger, at er gods transporteret på dæk i strid med en udtrykkelig aftale om transport under dæk, har transportøren ikke ret til ansvarsbegrænsning. Så skal han betale hele tabet. Men der skal stadig være et tab. I GPE blev kammer 3 sejlet på dæk i strid med aftalen, men det kom frem uskadt. Så var der ingen erstatning.",
 p:"SL § 284 stk. 2."},
{k:"so", q:"Hvornår skal modtageren reklamere over en skjult skade efter søloven?",
 o:["Skriftligt senest 3 dage efter udleveringen","Inden 7 dage","Inden 21 dage","Inden 1 år"],
 f:"Søloven § 288 siger: Synlig skade skal meldes skriftligt ved udleveringen. Skjult skade skal meldes skriftligt senest 3 dage efter udleveringen. Ellers formodes godset at være udleveret i orden. Men det er kun en bevisregel. Kunden kan stadig føre modbevis. Ved forsinkelse skal der reklameres inden 60 dage, ellers mister man kravet.",
 p:"SL § 288."},
{k:"so", q:"Hvad sker der, hvis modtageren ikke reklamerer over en forsinkelse inden 60 dage efter søloven?",
 o:["Transportøren er ikke ansvarlig for forsinkelsen","Fristen forlænges automatisk","Kunden får dobbelt erstatning","Det har ingen betydning"],
 f:"Søloven § 288 stk. 3 siger, at transportøren ikke er ansvarlig for tab som følge af forsinkelse, medmindre der er givet skriftlig underretning inden 60 dage efter, at godset blev overleveret. Ifølge Karnov er det en egentlig reklamationsregel: kravet tabes. Ved skade er det derimod kun en bevisregel.",
 p:"SL § 288 stk. 3. Karnov-noter 613-614."},
{k:"so", q:"Hvad er et konnossement (B/L)?",
 o:["Et dokument, der beviser aftalen og modtagelsen af godset, og som giver ret til godset","En forsikringspolice","En faktura fra sælger","En toldangivelse"],
 f:"Søloven § 292 siger, at et konnossement er bevis for aftalen om søtransport og for, at transportøren har modtaget godset, og at godset kun udleveres mod dokumentet. Det har tre funktioner: bevis for aftalen, kvittering for godset og dets stand, og et værdipapir, der kan sælges videre. En søfragtseddel (§ 308) kan ikke sælges videre.",
 p:"SL §§ 292 og 308."},
{k:"so", q:"Transportøren udsteder et B/L uden forbehold. Hvad betyder det?",
 o:["Det er bevis for, at godset blev modtaget i den stand, der er beskrevet","At godset ikke er forsikret","At transportøren ikke har ansvar","At godset må sejles på dæk"],
 f:"Søloven § 299 siger, at konnossementet er bevis for, at transportøren har modtaget godset som beskrevet, hvis der ikke er taget forbehold. Mangler oplysning om tilstanden, formodes godset at have været i god stand. Har en tredjemand købt B/L i god tro, må transportøren slet ikke føre modbevis (stk. 3). I GPE tog den første transportør ikke forbehold, men den anden gjorde. Det taler for, at skaden skete hos den første.",
 p:"SL §§ 298-299."},
{k:"so", q:"En undertransportør laver skaden til søs. Hvem er ansvarlig over for kunden?",
 o:["Transportøren, som om han selv havde udført hele transporten","Kun undertransportøren","Ingen","Kun kaptajnen"],
 f:"Søloven § 285 siger, at udføres transporten af en undertransportør, er transportøren stadig ansvarlig, som om han selv havde udført hele transporten. Kun hvis det udtrykkeligt er aftalt, at en navngiven undertransportør udfører en bestemt del, kan transportøren tage forbehold (stk. 2). Undertransportøren kan også selv hæfte efter § 286, og de hæfter solidarisk efter § 287.",
 p:"SL §§ 285-287."},
{k:"so", q:"Hvor beregnes godsets værdi efter søloven § 279?",
 o:["På det sted og tidspunkt, hvor godset blev eller skulle have været udleveret","Hvor godset blev afsendt","Hvor køberen bor","Hvor retssagen føres"],
 f:"Søloven § 279 siger, at erstatningen beregnes ud fra værdien af gods af samme slags på det sted og tidspunkt, hvor godset blev eller skulle have været udleveret. Først børspris, ellers markedspris, ellers sædvanlig værdi. Pas på: CMR § 29 regner værdien på afsendelsesstedet. Det er en typisk fælde.",
 p:"SL § 279, CMR § 29."},
{k:"so", q:"Hvad er forældelsesfristen for krav efter søloven kapitel 13?",
 o:["1 år","2 år","3 år","5 år"],
 f:"Krav om godsskade efter kapitel 13 forældes efter 1 år efter sølovens § 501. Søloven § 254 gør fristen præceptiv, så den kan ikke aftales kortere til skade for kunden.",
 p:"SL § 501 og § 254."},
{k:"so", q:"Er søloven kapitel 13 præceptiv?",
 o:["Ja, aftaler der gør det værre for kunden er ugyldige, men transportøren må påtage sig mere","Nej, alt kan aftales","Ja, og transportøren må heller ikke påtage sig mere","Kun for indenrigsfart"],
 f:"Søloven § 254 siger, at bestemmelser i en aftale eller et transportdokument er ugyldige, i det omfang de afviger fra kapitel 13. Men stk. 2 siger, at transportøren gerne må udvide sit ansvar. Det kaldes beskyttelsespræceptivt: man må ikke gøre det værre for kunden, men gerne bedre. Nogle paragraffer, fx §§ 255 og 258-261, kan dog fraviges.",
 p:"SL § 254."},

// ===================== CMR =====================
{k:"cmr", q:"Hvad er ansvarsgrundlaget i CMR § 24?",
 o:["Objektivt ansvar med fritagelser","Culpa med omvendt bevisbyrde","Almindelig culpa","Intet ansvar"],
 f:"CMR § 24 siger, at fragtføreren er ansvarlig for bortkomst og beskadigelse fra overtagelsen til afleveringen og for forsinket aflevering. Der står intet om skyld. Derfor er det objektivt ansvar. Fragtføreren kan dog slippe, hvis han beviser en af fritagelserne i § 24 stk. 2 eller § 25. Karnov kalder det et strengt, objektivt ansvar.",
 p:"CMR §§ 24-25."},
{k:"cmr", q:"Kan fragtføreren slippe for ansvar, fordi bremserne på lastbilen svigtede?",
 o:["Nej, mangler ved køretøjet fritager aldrig","Ja, det er force majeure","Ja, hvis lastbilen var lejet","Kun hvis lastbilen var ny"],
 f:"CMR § 24 stk. 3 siger, at fragtføreren ikke kan befri sig for ansvar ved at påberåbe sig mangler ved det køretøj, han brugte, eller fejl hos den, han har lejet køretøjet af. Det gælder, selv om han har passet lastbilen efter færdselsloven. Lastbilen er fragtførerens ansvar.",
 p:"CMR § 24 stk. 3."},
{k:"cmr", q:"Hvilken af disse er en fritagelse i CMR § 25?",
 o:["Læsning eller stuvning udført af afsenderen","Tyveri fra en ubevogtet parkeringsplads","Fejl ved lastbilens køleanlæg","Chaufførens for hurtige kørsel"],
 f:"CMR § 25 stk. 1 har listen: a) åbne køretøjer uden presenning efter udtrykkelig aftale i fragtbrevet, b) manglende eller dårlig indpakning, c) behandling, læsning, stuvning eller aflæsning udført af afsender eller modtager, d) visse godsarters natur som brud, rust og fordærv, e) forkerte mærker, f) levende dyr. Tyveri, fejl ved køleanlæg og for hurtig kørsel er fragtførerens egne forhold.",
 p:"CMR § 25."},
{k:"cmr", q:"Muuh: Gravkoen blev kørt på åben trailer uden presenning. Det stod i tilbuddet. Hvad kræver CMR § 25 litra a for at fritage?",
 o:["At aftalen er udtrykkelig og står i fragtbrevet","At kunden har betalt ekstra","At det regnede","At chaufføren tjekkede maskinen"],
 f:"§ 25 litra a fritager kun ved brug af åbne køretøjer uden presenning 'efter udtrykkelig aftale, som er optaget i fragtbrevet'. Står aftalen kun i tilbuddet og ikke i CMR-fragtbrevet, kan LED måske ikke bruge fritagelsen. Det er en vigtig detalje til eksamen. Loftet ville i øvrigt være 5.480 kg x 8,33 SDR, ca. 422.000 kr., så skaden på 10.000 euro er dækket.",
 p:"CMR § 25 stk. 1 litra a."},
{k:"cmr", q:"Hvad er særligt ved bevisbyrden i CMR § 25 stk. 2?",
 o:["Fragtføreren skal kun vise, at skaden KAN skyldes en af farerne, så skal kunden bevise det modsatte","Kunden skal altid bevise alt","Fragtføreren skal bevise præcis, hvad der skete","Der er ingen bevisbyrde"],
 f:"Efter § 24 stk. 2 skal fragtføreren fuldt bevise fritagelsen. Efter § 25 stk. 2 er det lettere: han skal kun godtgøre, at skaden under omstændighederne kan være opstået på grund af en af farerne i § 25. Så lægges det til grund, medmindre kunden beviser, at det ikke er tilfældet. Men § 25 gælder kun skade og bortkomst, ikke forsinkelse.",
 p:"CMR § 25 stk. 2. Karnov-note 91."},
{k:"cmr", q:"Afsenderen læssede godset, men chaufføren kunne tydeligt se, at læsset var farligt. Kan fragtføreren bruge § 25 litra c?",
 o:["Næppe, chaufføren skal gribe ind, når han kan se, at læsset er farligt","Ja, altid når afsender har læsset","Ja, fordi chaufføren ikke læssede","Kun hvis afsenderen er professionel"],
 f:"Karnov-noten til § 25 litra c siger, at fragtføreren kan blive ansvarlig, selv om afsender læssede, hvis chaufføren burde have set, at der var fare for, at læsset ville skride. Han har pligt til at gribe ind, også af hensyn til færdselssikkerheden (U 1979 335 H). Har chaufføren ikke særlig grund til at se en fejl, frifindes fragtføreren (U 1980 96 H). Det er kernen i Retsbogen-sagen om Bonus Wind.",
 p:"CMR § 25 stk. 1 litra c. Karnov-note 87."},
{k:"cmr", q:"Hvad er loftet over erstatning for skade efter CMR?",
 o:["8,33 SDR pr. kg bruttovægt plus fragt, told og omkostninger","667 SDR pr. kollo","26 SDR pr. kg","17 SDR pr. kg"],
 f:"CMR § 29 stk. 2 siger, at erstatningen ikke kan overstige 8,33 SDR for hvert kg manglende bruttovægt. Stk. 3 siger, at fragt, told og andre omkostninger ved transporten også erstattes. Ved skade (§ 31) betales værdiforringelsen, dog højst det, der skulle have været betalt, hvis den del var gået tabt.",
 p:"CMR §§ 29 og 31."},
{k:"cmr", q:"Vaskeriet: 9 tørretumblere á 150 kg og 17.000 kr. er ødelagt. Hvad er CMR-loftet? (kurs 9,25)",
 o:["Ca. 104.000 kr. (1.350 kg x 8,33 SDR)","153.000 kr.","Ca. 25.000 kr. (1.350 kg x 2 SDR)","Ca. 325.000 kr. (1.350 kg x 26 SDR)"],
 f:"Vægt: 9 x 150 = 1.350 kg. Loft: 1.350 x 8,33 = 11.245,5 SDR. Gange 9,25 = ca. 104.000 kr. Tabet er 9 x 17.000 = 153.000 kr. Uden gennembrud mangler kunden ca. 49.000 kr. 2 SDR er sølovens kilosats, og 26 SDR er luftfartens. Med kurs 9,16 som i fremlæggelsen bliver det 103.009 kr.",
 p:"CMR § 29 stk. 2."},
{k:"cmr", q:"Hvad er loftet ved forsinkelse efter CMR?",
 o:["Fragtbeløbet","2,5 gange fragten","8,33 SDR pr. kg","4 gange fragten"],
 f:"CMR § 32 siger, at godtgøres det, at der er lidt skade som følge af forsinkelse, skal fragtføreren erstatte skaden, dog ikke ud over fragtbeløbet. Kunden skal selv bevise tabet. 2,5 gange fragten er søloven, og 4 gange fragten er CIM.",
 p:"CMR § 32."},
{k:"cmr", q:"Hvornår kan godset betragtes som bortkommet efter CMR?",
 o:["30 dage efter den aftalte frist, eller 60 dage efter overtagelsen, hvis ingen frist er aftalt","Efter 7 dage","Efter 1 år","Efter 21 dage"],
 f:"CMR § 28 siger, at godset kan betragtes som bortkommet, hvis det ikke er afleveret inden 30 dage efter udløbet af den aftalte afleveringsfrist, eller inden 60 dage efter overtagelsen, hvis ingen frist er aftalt. Så kan kunden kræve erstatning som for tab.",
 p:"CMR § 28."},
{k:"cmr", q:"Hvornår er der gennembrud efter CMR § 37?",
 o:["Ved forsæt eller grov uagtsomhed hos fragtføreren eller nogen, han hæfter for efter § 4","Kun ved fragtførerens egen forsæt","Aldrig","Ved enhver fejl"],
 f:"CMR § 37 stk. 1 siger, at har fragtføreren forvoldt skaden med forsæt eller grov uagtsomhed, kan han ikke bruge loftet eller fritagelserne. Stk. 2 siger, at det samme gælder, hvis andre, han hæfter for efter § 4, har handlet sådan i tjenesten. Det omfatter chaufføren og undertransportøren. Her er CMR strengere end NSAB og søloven.",
 p:"CMR § 37."},
{k:"cmr", q:"Helt i fisk: Undertransportøren GT samlastede medicin med fisk trods skriftlig instruks. Hvorfor betyder det noget, om man bruger CMR eller NSAB?",
 o:["I CMR tæller undertransportørens grove uagtsomhed til gennembrud, i NSAB kræves forsæt","Der er ingen forskel","NSAB giver altid fuld erstatning","CMR har ikke gennembrud"],
 f:"Loftet er kun 163 kg x 8,33 SDR, ca. 12.560 kr., men tabet er ca. 660.000 kr. Gennembrud er afgørende. CMR § 37 stk. 2 siger, at grov uagtsomhed hos nogen, fragtføreren hæfter for (§ 4), giver gennembrud. GT brød bevidst en skriftlig instruks, hvilket taler for grov uagtsomhed eller forsæt. Efter NSAB § 6 stk. 2 kræves forsæt hos undertransportøren. Valget af regler kan altså afgøre, om kunden får 12.560 kr. eller 660.000 kr.",
 p:"CMR §§ 4 og 37, NSAB § 6 stk. 2. Løsningsforslag."},
{k:"cmr", q:"Hvad lægger domstolene vægt på, når de vurderer grov uagtsomhed ved tyveri fra en parkeret lastbil?",
 o:["Risikoen, sikring af vognen, om det er tyvevarer, og om parkeringen var nødvendig og sikret","Kun hvor dyrt godset var","Kun chaufførens alder","Kun om politiet blev ringet op"],
 f:"Karnov-noten til CMR § 37 nævner fire ting. 1) Om der var en særlig risiko, der krævede ekstra påpasselighed. 2) Om vogn og gods var sikret. 3) Om det var værdifulde tyvevarer som elektronik, cigaretter og mobiler. 4) Om parkeringen var nødvendig, og om stedet var sikret eller frit tilgængeligt. I U 2002 6/2 H blev videokameraer parkeret i et øde industrikvarter, selv om der var en sikret plads tæt på. Det var grov uagtsomhed.",
 p:"CMR § 37. Karnov-note 114."},
{k:"cmr", q:"DSV og Lego: DSV og Lego havde aftalt, at DSV i visse tilfælde skulle betale fuld erstatning. Hvad er problemet efter CMR?",
 o:["CMR § 1 stk. 3 gør aftaler, der fraviger loven, ugyldige, ifølge Karnov også til fordel for kunden","Der er intet problem","Aftalen gælder kun i Tjekkiet","Lego skulle have brugt søloven"],
 f:"CMR § 1 stk. 3 siger, at aftaler, der fraviger loven, er ugyldige. Ifølge Karnov-noten gælder det også aftaler, der er til fordel for kunden, fx at fragtføreren påtager sig mere ansvar. Det er strengere end søloven og luftfartsloven. Vil man have et højere loft i CMR, skal man bruge angiven værdi (§ 30) eller særlig interesse (§ 33) i fragtbrevet.",
 p:"CMR § 1 stk. 3, §§ 30 og 33. Karnov-note 6."},
{k:"cmr", q:"Hvorfor er det vigtigt, at chaufføren tager forbehold i CMR-fragtbrevet?",
 o:["Uden begrundet forbehold formodes godset at have været i god stand ved overtagelsen","Fordi ellers gælder søloven","Fordi forbehold hæver loftet","Det er ikke vigtigt"],
 f:"CMR § 10 siger, at fragtføreren ved overtagelsen skal tjekke antal kolli, mærker og godsets og emballagens synlige tilstand. § 11 stk. 2 siger, at har han ikke taget et begrundet forbehold, formodes godset at have været i god stand. Et trykt standardforbehold på formularen tæller ikke. Så kan han ikke bagefter sige, at skaden var der i forvejen.",
 p:"CMR §§ 10-11."},
{k:"cmr", q:"Hvornår skal modtageren reklamere over en skjult skade efter CMR?",
 o:["Skriftligt inden 7 dage, søn- og helligdage ikke medregnet","Inden 3 dage","Inden 14 dage","Inden 60 dage"],
 f:"CMR § 38 stk. 1 siger: Synlig skade skal gøres gældende senest ved afleveringen. Skjult skade skal gøres gældende skriftligt inden 7 dage, søn- og helligdage ikke medregnet. Ellers formodes godset modtaget i den stand, fragtbrevet siger. I Muuh blev gravkoen modtaget uden anmærkning, og skaden på ledningerne var skjult.",
 p:"CMR § 38 stk. 1."},
{k:"cmr", q:"Hvornår skal man reklamere over forsinkelse efter CMR, og hvad sker der, hvis man ikke gør?",
 o:["Skriftligt inden 21 dage, ellers betales ingen erstatning for forsinkelsen","Inden 60 dage, ellers halveres erstatningen","Inden 7 dage, men det har ingen følger","Man behøver aldrig at reklamere"],
 f:"CMR § 38 stk. 3 siger, at erstatning for forsinket aflevering kun skal betales, hvis modtageren inden 21 dage efter, at godset blev stillet til hans rådighed, skriftligt har meddelt fragtføreren, at han vil påberåbe sig forsinkelsen. Ved forsinkelse mister man altså kravet. Ved skade er § 38 stk. 1 en bevisregel.",
 p:"CMR § 38 stk. 3."},
{k:"cmr", q:"Hvad er forældelsesfristen efter CMR?",
 o:["1 år, eller 3 år ved forsæt eller grov uagtsomhed","2 år","6 måneder","5 år"],
 f:"CMR § 41 siger, at søgsmål skal anlægges inden et år, eller inden tre år, hvis der er udvist forsæt eller grov uagtsomhed. Fristen løber ved skade og forsinkelse fra afleveringen. Et skriftligt krav stopper fristen, indtil fragtføreren skriftligt afviser det.",
 p:"CMR § 41."},
{k:"cmr", q:"Hvor beregnes godsets værdi efter CMR § 29?",
 o:["På stedet og tidspunktet for overtagelsen til transport","Hvor godset skulle udleveres","Hvor kunden har sin bank","Hvor retssagen føres"],
 f:"CMR § 29 stk. 1 siger, at erstatning beregnes efter godsets værdi på stedet og tidspunktet for overtagelsen. Først børspris, så markedspris, så sædvanlig værdi. Søloven § 279 bruger derimod udleveringsstedet. Forskellen er en typisk fælde.",
 p:"CMR § 29 stk. 1."},
{k:"cmr", q:"Kan kunden undgå CMR-loftet ved at kræve erstatning uden for kontrakt?",
 o:["Nej, fragtføreren og hans folk kan også bruge lovens begrænsninger da","Ja, så gælder intet loft","Ja, men kun i Danmark","Kun hvis kunden er forbruger"],
 f:"CMR § 36 siger, at kræves erstatning for bortkomst, skade eller forsinkelse på andet grundlag end aftale, kan fragtføreren og dem, han hæfter for efter § 4, alligevel bruge lovens regler om fritagelse og loft. Det samme står i søloven § 282. Det kaldes ofte Himalaya-reglen.",
 p:"CMR § 36, SL § 282."},

// ===================== LUFT OG TOG =====================
{k:"luft", q:"Hvad er ansvarsgrundlaget for skade på gods i luftfartsloven?",
 o:["Objektivt ansvar (§ 108)","Culpa med omvendt bevisbyrde","Almindelig culpa","Intet ansvar"],
 f:"Luftfartsloven § 108 siger, at befordreren er ansvarlig for skade, når gods går tabt eller beskadiges, mens det er i hans varetægt. Der står intet om skyld, så det er objektivt ansvar. Han kan kun slippe ved de fire fritagelser i stk. 2. For forsinkelse gælder en anden regel, § 109.",
 p:"LFL § 108."},
{k:"luft", q:"Hvad er ansvarsgrundlaget for forsinkelse i luftfartsloven?",
 o:["Culpa med omvendt bevisbyrde (§ 109)","Objektivt ansvar","Intet ansvar ved forsinkelse","Almindelig culpa"],
 f:"Luftfartsloven § 109 siger, at befordreren er ansvarlig for forsinkelse, hvis han ikke beviser, at han og hans folk har taget alle forholdsregler, som med rimelighed kan kræves, eller at det ikke var muligt. Det er culpa med omvendt bevisbyrde. CJ: 'To forskellige standarder' i luftfart, objektivt for skade og omvendt bevisbyrde for forsinkelse.",
 p:"LFL § 109. CJ lektion 6."},
{k:"luft", q:"Hvad er loftet for gods i luftfartsloven?",
 o:["26 SDR pr. kg","22 SDR pr. kg","8,33 SDR pr. kg","2 SDR pr. kg"],
 f:"Luftfartsloven § 111 stk. 5 siger, at befordrerens ansvar for gods, der går tabt, beskadiges eller forsinkes, er begrænset til 26 SDR pr. kg. Det er samme sats for skade og forsinkelse. Pas på: dine gamle noter skrev 22 SDR. Det er forkert. Loven og CJ's slides siger 26.",
 p:"LFL § 111 stk. 5."},
{k:"luft", q:"Kan kunden få gennembrud til fuld erstatning for gods med fly ved grov uagtsomhed?",
 o:["Nej, der findes ikke gennembrud for gods i luftfart","Ja, altid","Ja, efter § 37","Kun ved forsinkelse"],
 f:"I luftfart findes der ikke gennembrud for gods. § 111 stk. 6 fjerner kun loftet for passagerforsinkelse og bagage. CJ skrev i Furs & Feathers: 'Om den rækker til at dække tabet, så fint, men uanset så er der ikke nogen mulighed for at søge gennembrud til fuld erstatning.' Kun en særlig erklæring om interesse mod tillæg (§ 111 stk. 5) eller en aftale (§ 113) kan hæve loftet.",
 p:"LFL § 111 stk. 5-6 og § 113."},
{k:"luft", q:"Hvilke fritagelser har befordreren for skade på gods efter luftfartsloven § 108 stk. 2?",
 o:["Godsets egen beskaffenhed, mangelfuld emballering udført af andre, krig og offentlige myndigheders handlinger","Alle forhold uden for hans kontrol","Hårdt vejr og nautiske fejl","Ingen fritagelser"],
 f:"§ 108 stk. 2 har kun fire fritagelser: 1) godsets egen beskaffenhed eller fejl, 2) mangelfuld emballering udført af andre end befordreren, 3) krigshandling eller væbnet konflikt, 4) offentlige myndigheders handlinger ved ind- og udførsel. Listen er kort, så det er svært for befordreren at slippe.",
 p:"LFL § 108 stk. 2."},
{k:"luft", q:"Hvornår skal man reklamere over skade på gods sendt med fly?",
 o:["Straks og senest 14 dage efter modtagelsen","Inden 3 dage","Inden 7 dage","Inden 60 dage"],
 f:"Luftfartsloven § 115 stk. 2 siger, at ved skade på gods skal der gives meddelelse umiddelbart efter, at skaden er opdaget, og senest 14 dage efter modtagelsen. Ved forsinkelse inden 21 dage. § 116 siger, at gives meddelelsen ikke til tiden, bortfalder ethvert krav. I luftfart mister man altså kravet både ved skade og forsinkelse.",
 p:"LFL §§ 115-116."},
{k:"luft", q:"Hvad er forældelsesfristen i luftfartsloven?",
 o:["2 år","1 år","3 år","6 måneder"],
 f:"Luftfartsloven § 118 siger, at retten til erstatning bortfalder, hvis sagen ikke er anlagt inden 2 år fra flyets ankomst til bestemmelsesstedet, eller fra den dag, det skulle være ankommet. Det er længere end CMR, søloven og NSAB, som alle har 1 år.",
 p:"LFL § 118."},
{k:"luft", q:"Befordreren sender godset med lastbil i stedet for fly uden afsenderens samtykke. Hvad sker der?",
 o:["Den del regnes som lufttransport, så befordreren ikke får en bedre stilling","CMR gælder, og befordreren får lavere loft","Befordreren slipper for ansvar","Afsenderen mister sit krav"],
 f:"Luftfartsloven § 108 stk. 4 siger, at udskifter befordreren uden samtykke den aftalte luftbefordring med en anden transportform, regnes den del også som luftbefordring. Befordreren må ikke opnå en bedre retsstilling ved at skifte transportform.",
 p:"LFL § 108 stk. 4."},
{k:"luft", q:"Hvad er loftet for gods efter CIM (jernbane)?",
 o:["17 SDR pr. kg","8,33 SDR pr. kg","26 SDR pr. kg","667 SDR pr. kollo"],
 f:"CIM art. 30 § 2 siger, at erstatningen ikke må overstige 17 regneenheder (SDR) pr. kg manglende bruttovægt. Ved overskridelse af transittiden er loftet 4 gange fragten (art. 33). Gennembrud sker ved forsæt eller hensynsløs adfærd med viden om, at skade sandsynligvis ville ske (art. 36).",
 p:"CIM art. 30, 33 og 36."},
{k:"luft", q:"Hvornår kan godset regnes som tabt efter CIM?",
 o:["30 dage efter at transittiden er udløbet","60 dage efter overtagelsen","7 dage efter aftalt tid","1 år efter afsendelsen"],
 f:"CIM art. 29 siger, at den berettigede uden yderligere bevis kan regne godset som tabt, når det ikke er udleveret inden 30 dage efter udløbet af transittiden. Forældelsesfristen i CIM er 1 år, eller 2 år ved forsæt (art. 48).",
 p:"CIM art. 29 og 48."},

// ===================== KØBERET OG INCOTERMS =====================
{k:"kob", q:"Hvorfor starter man med købsaftalen i en transportopgave?",
 o:["Fordi den afgør, hvem der bærer risikoen og dermed har kravet mod transportøren","Fordi købeloven altid gælder for transporten","Fordi transportøren er part i købsaftalen","Det gør man ikke"],
 f:"Incotermen eller købeloven afgør, hvornår risikoen går fra sælger til køber. Den, der bærer risikoen, når skaden sker, har tabet. Det er også den, der har kravet mod transportøren. Den anden part er så ude af billedet. CJ skriver tit: 'Køber er dermed ikke længere med i projektet' (GPE) eller 'Hamburg-køberen er ude af billedet' (Furs & Feathers).",
 p:"KBL § 17, Incoterms 2020."},
{k:"kob", q:"Hvornår går risikoen over til køber ved FOB?",
 o:["Når varen er om bord på skibet i afskibningshavnen","Når varen er hos køber","Når varen forlader sælgers lager","Når køber har betalt"],
 f:"FOB betyder Free On Board. Sælger leverer, når varen er om bord på skibet i den aftalte havn. Fra det øjeblik bærer køber risikoen. Køber betaler sejladsen og forsikringen. I Papaya var der aftalt FOB Manzanillo. Derfor bar køber Maxi-Grossisten risikoen, og sælger var ude af sagen.",
 p:"Incoterms 2020: FOB."},
{k:"kob", q:"Ved CFR betaler sælger fragten. Hvem bærer risikoen under sejladsen?",
 o:["Køber, fordi risikoen går over, når varen er om bord","Sælger, fordi han betaler fragten","Transportøren","De deler risikoen"],
 f:"CFR betyder Cost and Freight. Sælger betaler fragten til bestemmelseshavnen, men risikoen går over til køber, når varen er om bord i afskibningshavnen. Det er en fælde: den, der betaler, er ikke den, der bærer risikoen. I Ost til Portugal var der aftalt CFR Sines. Køber Nyrup Mejeri bar risikoen fra Aarhus.",
 p:"Incoterms 2020: CFR."},
{k:"kob", q:"Ved DAP Hamburg sker der skade under transporten. Hvem har tabet?",
 o:["Sælger, fordi han bærer risikoen, indtil varen er stillet til rådighed i Hamburg","Køber","Transportøren alene","Ingen"],
 f:"DAP betyder Delivered At Place. Sælger bærer risiko og omkostninger, indtil varen er stillet til rådighed på det aftalte sted, klar til aflæsning. I Furs & Feathers var der aftalt DAP DSV-terminal Hamburg. Skaden skete før Hamburg. Derfor var det sælger FF, der havde tabet, og FF måtte rette kravet mod Blue Water. CJ: 'Sælger skylder køber!'",
 p:"Incoterms 2020: DAP. CJ's kommentarer til Furs & Feathers."},
{k:"kob", q:"Ved EXW, hvem bærer risikoen under hele transporten?",
 o:["Køber, fra varen er stillet til rådighed hos sælger","Sælger","Transportøren","Sælger indtil grænsen"],
 f:"EXW betyder Ex Works. Sælger stiller varen til rådighed på sit eget sted, og sælger læsser ikke engang. Køber henter og bærer al risiko derfra. Kampvognene i kampvogn-opgaven blev solgt EXW. Derfor var det køberen, der havde kravet mod transportøren Frode Larsen.",
 p:"Incoterms 2020: EXW."},
{k:"kob", q:"Hvad er forskellen på DAP, DPU og DDP?",
 o:["DAP: klar til aflæsning. DPU: sælger aflæsser også. DDP: sælger betaler også importtold","Der er ingen forskel","DPU er kun til skib","DDP betyder, at køber betaler alt"],
 f:"Alle tre er leveringer på bestemmelsesstedet, hvor sælger bærer risikoen under transporten. DAP: varen er klar til aflæsning, og køber aflæsser og klarerer import. DPU: sælger aflæsser også. Det er den eneste Incoterm, hvor sælger aflæsser. DDP: sælger betaler også importtold og klarerer importen.",
 p:"Incoterms 2020."},
{k:"kob", q:"Jack & Jeans: Ingen Incoterm. Sælger sender jeansene med sin sædvanlige vognmand. Hvornår er der leveret?",
 o:["Når jeansene er overgivet til vognmanden (forsendelseskøb)","Når de er hos køber i Århus","Når køber har betalt","Når fakturaen er sendt"],
 f:"Uden Incoterm bruger man købelovens deklaratoriske regler i §§ 9-11. Skal varen sendes med en selvstændig fragtfører, er det et forsendelseskøb, og levering sker ved overgivelse til fragtføreren (§ 10). Vognmanden er selvstændig, ikke ansat hos sælger. Derfor var der leveret, og risikoen var gået over til køber (§ 17). Køber bar tabet på de 20 par.",
 p:"KBL §§ 10 og 17. CJ's bemærkninger."},
{k:"kob", q:"Hvad sagde CJ om Jack & Jeans, hvis man i stedet går ud fra, at der var aftalt DAP?",
 o:["Så var der ikke leveret, og der manglede 20 par, men manglen var ikke væsentlig","Så skulle køber betale dobbelt","Så var vognmanden ansvarlig for alt","Så gjaldt CMR"],
 f:"CJ's alternative løsning: Ved DAP er der ikke leveret, da uheldet sker. Så er leveringen mangelfuld, fordi der kun kommer 780 af 800 par. Jeans er genusvarer, så køber kan kræve omlevering (send 20 par mere) eller afslag. Manglen er ikke væsentlig, fordi 97,5 procent er leveret, så køber kan ikke hæve. Erstatning: objektivt ansvar efter KBL § 43, jf. § 24.",
 p:"KBL §§ 42-43 og 24. CJ's bemærkninger."},
{k:"kob", q:"Hvad er forskellen på genusvarer og speciesvarer i forhold til erstatning?",
 o:["Genus: objektivt ansvar (KBL § 24). Species: culpa med omvendt bevisbyrde (KBL § 23)","Der er ingen forskel","Species: objektivt ansvar. Genus: intet ansvar","Begge er culpa"],
 f:"Genusvarer er bestemt efter art, fx 800 par jeans, som sælger kan tage fra lageret. Speciesvarer er én bestemt ting. KBL § 24 giver objektivt ansvar for genus: sælger skal betale, medmindre han har taget forbehold, eller det var umuligt af uforudsete grunde. KBL § 23 giver culpa med omvendt bevisbyrde for species. Omlevering kan kun kræves ved genus.",
 p:"KBL §§ 23-24."},
{k:"kob", q:"Gælder CISG for et køb mellem en sælger i Nuuk og en køber i Tyskland?",
 o:["Ikke direkte, fordi Danmark har taget forbehold for Grønland (art. 93)","Ja, altid","Nej, fordi Tyskland ikke er med i CISG","Kun ved skibstransport"],
 f:"CISG gælder ved køb mellem parter i forskellige lande. Men Danmark har efter art. 93 erklæret, at CISG ikke gælder for Grønland og Færøerne. Derfor er art. 1 stk. 1 litra a ikke opfyldt for en sælger i Nuuk. CISG kan komme ind via litra b, hvis lovvalget fører til fx tysk ret. Det nordiske forbehold i art. 94 betyder ikke noget her, fordi Tyskland ikke er nordisk.",
 p:"CISG art. 1, 93 og 94."},
{k:"kob", q:"Hvad kan køber gøre, hvis der leveres for lidt?",
 o:["Kræve efterlevering af det manglende, afslag eller erstatning","Kun hæve købet","Intet","Kræve dobbelt levering"],
 f:"KBL § 50 siger, at reglerne om mangler gælder tilsvarende, når den leverede mængde er for lille. Køber kan ikke kræve omlevering af det hele, men kan kræve det manglende efterleveret. Køber kan også kræve forholdsmæssigt afslag eller erstatning. Hæve kan han kun, hvis manglen er væsentlig.",
 p:"KBL § 50."},
{k:"kob", q:"Hvad er ansvarsgrundlaget i CISG art. 74?",
 o:["Objektivt ansvar, men kun for tab, der kunne forudses","Culpa med omvendt bevisbyrde","Almindelig culpa","Intet ansvar"],
 f:"CISG art. 74 siger, at erstatning svarer til tabet, inkl. tabt fortjeneste, som følge af misligholdelsen. Men den må ikke overstige det tab, den misligholdende part forudså eller burde forudse, da aftalen blev lavet. Der står intet om culpa, så det er objektivt ansvar. Begrænsningen hedder adækvans.",
 p:"CISG art. 74. CJ lektion 1."},
{k:"kob", q:"I handelskøb efter købeloven: hvornår er en forsinkelse væsentlig?",
 o:["Enhver forsinkelse er væsentlig, medmindre kun en ringe del er forsinket","Kun ved mere end 30 dages forsinkelse","Aldrig","Kun ved forsinkelse over 60 dage"],
 f:"KBL § 21 stk. 3 siger, at i handelskøb anses enhver forsinkelse for væsentlig, medmindre det kun er en ringe del af det solgte, der er forsinket. Derfor kan køber hæve. Ved successiv levering kan køber efter § 22 som udgangspunkt kun hæve for den forsinkede levering.",
 p:"KBL §§ 21-22."},

// ===================== OPGAVER (CASES) =====================
{k:"case", q:"Furs & Feathers: Sending 3 vejer 29 kg, halvdelen er ødelagt, værdi 27.711 kr. pr. sending. Hvad er NSAB-erstatningen? (kurs 9,32)",
 o:["Ca. 1.126 kr. (14,5 kg x 8,33 x 9,32)","13.855,50 kr.","Ca. 3.500 kr. (14,5 kg x 26 x 9,32)","27.711 kr."],
 f:"Halvdelen af 29 kg er 14,5 kg. NSAB § 21: 8,33 SDR pr. kg. 14,5 x 8,33 x 9,32 = 1.125,72 kr. Tabet er halvdelen af 27.711 = 13.855,50 kr. Derfor mangler FF 12.729,78 kr., som ikke dækkes. Svaret med 26 SDR ville gælde, hvis man ved, at skaden skete i flyet. Det er CJ's beregning.",
 p:"NSAB § 21. CJ's løsning lektion 6."},
{k:"case", q:"Papaya: Hvorfor brugte CJ søloven, selv om TotalTransport var speditør efter NSAB?",
 o:["Fordi NSAB § 2 sender til søloven, når skaden skete i søtransportørens varetægt","Fordi NSAB aldrig gælder ved frugt","Fordi køber valgte søloven","Fordi CMR ikke gælder i Panama"],
 f:"TotalTransport er formentlig medlem af Danske Speditører, så NSAB gælder. Men NSAB § 2 siger, at ved man, hvor skaden skete, bruges loven for den transportform. Containeren blev fejlagtigt losset i Dunkerque, og temperaturen var for lav, mens den stod på havnen. Søtransportørens varetægt efter SL § 274 omfatter havnen. Derfor sendte NSAB sagen til søloven.",
 p:"NSAB § 2, SL § 274. CJ's vejledende besvarelse."},
{k:"case", q:"Skælskør: Container 1 står glemt på havnen i Aarhus i 62 dage. Hvad er det vigtigste juridiske greb?",
 o:["Efter 60 dage kan kunden kræve erstatning som for tab efter SL § 278 stk. 3","Syltetøj er letfordærveligt, så ingen erstatning","CMR gælder, fordi lastbilen hentede containeren","Køber i USA bærer risikoen"],
 f:"Containeren stod på havnen hos rederiet, altså i søtransportørens varetægt (SL § 274). NSAB § 2 sender til søloven. Efter § 278 stk. 3 kan der kræves erstatning som for tab, når godset ikke er udleveret inden 60 dage. Loft: 14 paller x 1.100 kg = 15.400 kg x 2 SDR = 30.800 SDR, ca. 284.900 kr. Tabet er 1,4 mio. kr. Der var aftalt DAP, så sælger Skælskør har kravet.",
 p:"SL §§ 274, 278 stk. 3 og 280. Løsningsforslag."},
{k:"case", q:"Kampvogne: Vægt 66.500 kg pr. kampvogn, skade 1.434.832 kr. Skal man diskutere gennembrud?",
 o:["Nej, loftet er ca. 5,1 mio. kr. og dækker hele skaden","Ja, loftet dækker kun en lille del","Ja, fordi det er militært udstyr","Nej, fordi der ikke er noget loft i CMR"],
 f:"Regn altid loftet først. 66.500 kg x 8,33 SDR = 553.945 SDR. Gange 9,25 = ca. 5,1 mio. kr. Skaden er 1,43 mio. kr. Den er altså dækket inden for loftet. Så er gennembrud ikke nødvendigt. Tungt gods giver et højt loft i CMR.",
 p:"CMR § 29. Løsningsforslag."},
{k:"case", q:"PH Thomsen: 1.056 kasser á 68 kr. = 71.808 kr. CJ fandt et skæringspunkt på ca. 0,89 kg pr. kasse. Hvad betyder det?",
 o:["Vejer en kasse mindre end 0,89 kg, dækker NSAB-loftet ikke hele tabet","Vejer en kasse mere end 0,89 kg, får kunden ingen erstatning","Kasserne skal vejes om","Erstatningen er altid 0,89 kr. pr. kasse"],
 f:"CJ regnede baglæns. Tabet 71.808 kr. delt med kursen 9,185 = 7.817 SDR. Delt med 8,33 = 939 kg. Delt med 1.056 kasser = 0,89 kg pr. kasse. Vejer kasserne mindst 0,89 kg, dækker loftet hele tabet. Med 2,5 kg pr. kasse bliver loftet 201.219 kr., og så er der fuld dækning. Det er en god metode, når vægten ikke står i opgaven.",
 p:"NSAB § 21. CJ's gulerod-løsning."},
{k:"case", q:"Vaskeriet: Chaufføren surrede selv i hast. Kan Global Forwarding bruge CMR § 25 litra c (afsenders læsning)?",
 o:["Nej, når chaufføren selv surrede, er det ikke afsenders læsning","Ja, altid","Ja, fordi sælger stod for læsning","Kun hvis det regnede"],
 f:"§ 25 litra c fritager kun, når læsning, stuvning eller aflæsning er udført af afsenderen, modtageren eller nogen på deres vegne. I Vaskeriet surrede chaufføren selv. NSAB § 5 siger også, at speditøren står for stuvning og sikring. Derfor passer fritagelsen ikke. Global Forwarding er ansvarlig efter CMR § 24.",
 p:"CMR §§ 24-25, NSAB § 5. Løsningsforslag."},
{k:"case", q:"GPE: Kammer 2 får et hul under lastningen i København. Den første transportør tager ikke forbehold i B/L, men undertransportøren gør i Bremerhaven. Hvad viser det?",
 o:["Det taler for, at skaden skete i den første transportørs varetægt","At skaden skete i Barcelona","At GPE selv har skylden","At B/L er ugyldigt"],
 f:"Et B/L uden forbehold er bevis for, at godset var i orden, da transportøren modtog det (SL § 299). Undertransportøren noterede straks hullet i Bremerhaven. Derfor skete skaden mellem København og Bremerhaven. Begge dele er inden for varetægtsperioden (§ 274), og Holst er ansvarlig for hele transporten (§ 285). Ingen fritagelse passer, så der er ansvar efter § 275.",
 p:"SL §§ 274, 275, 285 og 299. CJ's GPE-bemærkninger."},
{k:"case", q:"Retsbogen (Bonus Wind mod DBS): Hvad er kernen i sagen?",
 o:["Læsning og surring: hvem læssede, og hvad tjekkede chaufføren","Forsinkelse over 60 dage","Om luftfartsloven gælder","Om CISG gælder"],
 f:"Bonus' lager læssede gearkasser og generatorer på en åben vogn uden friktionsmåtte og stropper. Chaufføren siger, at han tjekkede surringen. Efter CMR § 25 litra c kan DBS slippe, når afsender har læsset. Men kan chaufføren se, at læsset er farligt, skal han gribe ind. Hans egen forklaring om at have tjekket surringen kan vende sig mod DBS. Åben vogn kræver desuden aftale i fragtbrevet (§ 25 litra a).",
 p:"CMR §§ 4, 24 og 25. Retsbogen 27. oktober 2026."},
{k:"case", q:"Muuh: Kunden kræver også tabt arbejdsfortjeneste, fordi gravkoen ikke kunne starte. Hvad siger CMR?",
 o:["CMR giver kun godsets værdi plus fragt og told, ikke tabt fortjeneste","Kunden får altid tabt fortjeneste","Tabt fortjeneste dækkes op til 26 SDR pr. kg","Kun hvis gravkoen var ny"],
 f:"CMR § 29 og § 31 giver normalerstatning: godsets værdi eller værdiforringelse plus fragt, told og omkostninger. Tabt fortjeneste, driftstab og følgeskader dækkes ikke. Kun ved forsinkelse (§ 32) dækkes andre tab, og højst med fragtbeløbet. Kunden kunne kun få mere med en aftale om særlig interesse i fragtbrevet (§ 33). Reparationen på 10.000 euro er derimod dækket.",
 p:"CMR §§ 29, 31-33. Karnov-note 109."},
{k:"case", q:"Muuh: Leveringen var DAP Valencia. Hvem har kravet mod LED Logistics?",
 o:["Den danske sælger, fordi sælger bærer risikoen under transporten ved DAP","Den spanske køber","Chaufføren","Ingen"],
 f:"Ved DAP bærer sælger risikoen, indtil gravkoen er stillet til rådighed i Valencia. Skaden skete under transporten. Derfor er det den danske sælger, der har tabet og kravet mod LED. Den danske kunde sendte da også claimet til LED. Den spanske køber kan bruge sine køberetlige beføjelser mod sælger.",
 p:"Incoterms 2020: DAP."},
{k:"case", q:"DSV og Lego: Chaufføren parkerede, hvor Amazons personale anviste, fordi køretiden var ved at løbe ud. Hvad taler IMOD grov uagtsomhed?",
 o:["Parkeringen var nødvendig, stedet havde gadelys og var anvist af modtagerens personale","Godset var meget værdifuldt","Traileren stod frit tilgængeligt","Det skete om natten"],
 f:"Brug Karnovs fire kriterier. Imod grov uagtsomhed taler, at parkeringen var nødvendig på grund af køre- og hviletid, at stedet var anvist af modtagerens eget personale, og at der var gadelys. For grov uagtsomhed taler, at traileren stod frit tilgængeligt om natten med værdifuldt Lego-gods. I U 2003 1170 H var et kort stop på en rasteplads ikke grov uagtsomhed. Til eksamen skal du veje begge sider.",
 p:"CMR § 37. Karnov-note 114."},
{k:"case", q:"DSV og Lego: Tyveri om natten fra en parkeret trailer. Kan DSV slippe efter CMR § 24 stk. 2 ('forhold fragtføreren ikke kunne undgå')?",
 o:["Næppe, fritagelsen fortolkes meget snævert, som force majeure","Ja, tyveri fritager altid","Ja, hvis politiet blev kontaktet","Nej, fordi CMR ikke gælder i England"],
 f:"Karnov siger, at fritagelsen for forhold, fragtføreren ikke kunne undgå, skal fortolkes meget snævert, som force majeure. Tyveri fra et ubevogtet sted fritager sjældent. I U 1995 302 S blev fragtføreren ansvarlig for tyveri fra en ubevogtet parkeringsplads i Italien. Kun et røveri under forsvarlige omstændigheder er blevet anset for uundgåeligt (U 1983 585 S).",
 p:"CMR § 24 stk. 2. Karnov-note 82."},
{k:"case", q:"Helt i fisk: 3 paller medicin, 163 kg, værdi ca. 660.000 kr. Hvad er CMR-loftet uden gennembrud? (kurs 9,25)",
 o:["Ca. 12.560 kr.","Ca. 660.000 kr.","Ca. 3.000 kr.","Ca. 39.000 kr."],
 f:"163 kg x 8,33 SDR = 1.357,8 SDR. Gange 9,25 = ca. 12.560 kr. Det er under 2 procent af tabet. Derfor er gennembrud efter CMR § 37 helt afgørende. Med angiven værdi efter § 30 kunne afsender have sikret sig. Lektien: let og dyrt gods er meget dårligt dækket af kilo-lofter.",
 p:"CMR §§ 29, 30 og 37."},
{k:"case", q:"Får til Dublin: 75 får á 60 kg. Er hvert får en enhed, hvad er sølovens loft så bedst for kunden? (kurs 9,25)",
 o:["75 x 667 SDR = ca. 462.700 kr.","4.500 kg x 2 SDR = ca. 83.250 kr.","4.500 kg x 8,33 SDR","75 x 26 SDR"],
 f:"Efter vægt: 75 x 60 = 4.500 kg x 2 SDR = 9.000 SDR, ca. 83.250 kr. Efter enheder: 75 x 667 = 50.025 SDR, ca. 462.700 kr. Søloven § 280 siger, at det højeste gælder. Tabet er 75 x 1.000 euro, ca. 560.000 kr. Så selv med kolli-reglen mangler kunden noget. Det kræver, at dyrene er opgjort som enheder i transportdokumentet.",
 p:"SL § 280. Løsningsforslag."},
{k:"case", q:"Ost til Portugal: Container 2 blev glemt i Antwerpen og kom efter festivalen, men osten var i orden. Hvad er det juridiske problem?",
 o:["Forsinkelse, hvor loftet er højst 2,5 gange fragten, fordi 60 dage ikke er overskredet","Totaltab, fordi osten er ødelagt","Nautisk fejl","Ingen problemer, fordi osten er i orden"],
 f:"Osten fejlede ikke noget, men festivalen var overstået. Det er en forsinkelse efter SL § 278. Den var ikke på 60 dage, så den kan ikke behandles som totaltab (stk. 3). Erstatningen er højst 2,5 gange fragten for det forsinkede gods, dog højst den samlede fragt (§ 280 stk. 2). Kunden skal reklamere skriftligt inden 60 dage (§ 288 stk. 3).",
 p:"SL §§ 278, 280 stk. 2 og 288 stk. 3. CJ lektion 4."},
{k:"case", q:"Skælskør: Container 2 har vandskade, men man ved ikke, om det skete til søs eller på lastbilen i USA. Hvilke regler bruger man?",
 o:["NSAB's egne regler, fordi man ikke kan bevise, hvor skaden skete","Søloven, fordi containeren blev sejlet","CMR, fordi lastbilen kørte sidst","Amerikansk lov"],
 f:"Netværksreglen i NSAB § 2 kræver, at man kan bevise, hvor skaden skete, eller at transportformen er aftalt. Kan man ikke det, bliver man i NSAB §§ 15-21. Så er loftet 8,33 SDR pr. kg: 10 paller x 1.100 kg = 11.000 kg x 8,33 = 91.630 SDR, ca. 847.600 kr. Kan man bevise, at det skete til søs, giver søloven kun 22.000 SDR. Det kan altså betale sig for kunden ikke at kunne bevise søskaden.",
 p:"NSAB §§ 2 og 21, SL § 280. Løsningsforslag."},
{k:"case", q:"Jack & Jeans: Hvorfor er de 20 ødelagte par IKKE en mangel efter CJ's hovedløsning?",
 o:["Fordi risikoen var gået over ved overgivelsen til vognmanden, før uheldet skete","Fordi jeans ikke kan have mangler","Fordi køber ikke reklamerede","Fordi vognmanden havde skylden"],
 f:"Efter KBL § 44 bedømmes en mangel på det tidspunkt, hvor risikoen gik over til køber. I forsendelseskøb gik risikoen over, da jeansene blev overgivet til vognmanden (§ 10). Da var alle 800 par i orden. Uheldet skete bagefter. Derfor er der ingen mangel, og køber bærer tabet efter § 17.",
 p:"KBL §§ 10, 17 og 44."},
{k:"case", q:"Furs & Feathers: Hvorfor må man ikke bruge søloven i denne opgave?",
 o:["Fordi der ikke er nogen søtransport, kun fly og lastbil","Fordi skind er undtaget","Fordi Blue Water ikke ejer et skib","Fordi Grønland ikke har havne"],
 f:"Furs & Feathers sendes med fly fra Nuuk til København og lastbil fra København til Hamburg. Der er ingen søtransport. Søloven kapitel 13 gælder kun stykgodstransport til søs. De relevante regler er luftfartsloven, CMR-loven og NSAB. CJ nævner dog, at man ikke helt kan se af teksten, om Royal Arctic Line (skib) var med i stedet for Air Greenland.",
 p:"SL § 251-252, LFL § 90, CMR § 1. CJ lektion 6."},
{k:"case", q:"Papaya: Forsinkelsen af containeren var 3 dage. Hvorfor sagde CJ, at kunden hellere skal kræve erstatning for skaden?",
 o:["Fordi forsinkelses-loftet er højst 2,5 gange fragten, mens skade-loftet er langt højere","Fordi forsinkelse aldrig giver erstatning","Fordi 3 dage er for lidt til at klage","Fordi CMR gælder for forsinkelse"],
 f:"Søloven § 280 stk. 2 begrænser erstatning for forsinkelse til 2,5 gange fragten for den forsinkede container, højst hele fragten. Skaden på frugten giver derimod et loft på 2 SDR pr. kg eller 667 SDR pr. kollo. Det er meget mere. CJ skrev, at Maxi-Grossisten 'i stedet og med fordel' kan beregne kravet ud fra skaden fra temperaturen.",
 p:"SL § 280. CJ's vejledende besvarelse."},
{k:"case", q:"Helt i fisk: Godset blev afvist i Portugal, og lagret skrev det på CMR-fragtbrevet med billeder. Hvorfor er det vigtigt?",
 o:["Det er en rettidig reklamation over en synlig skade efter CMR § 38","Det gør godset til BWS' ejendom","Det betyder, at søloven gælder","Det har ingen betydning"],
 f:"CMR § 38 siger, at synlig skade skal gøres gældende senest ved afleveringen. Ellers formodes godset modtaget i den stand, fragtbrevet siger. Lagret skrev afvisningen og årsagen på fragtbrevet og tog billeder. Det sikrer beviset. En Lloyd surveyor bekræftede bagefter forløbet.",
 p:"CMR § 38."},
{k:"parter", q:"Hvad kalder NSAB den, der har lavet aftalen med speditøren?",
 o:["Ordregiveren","Aflasteren","Befordreren","Fragtføreren"],
 f:"NSAB § 4 siger, at ordregiveren er den, der har lavet aftalen med speditøren, eller den, der er trådt i hans sted. Ordregiverens ansvar står i § 26: han skal holde speditøren skadesløs, hvis fx oplysningerne om godset er forkerte, godset er dårligt emballeret, eller tilladelser mangler.",
 p:"NSAB §§ 4 og 26."},
{k:"parter", q:"Hvad kalder de forskellige love transportøren?",
 o:["Søloven: transportør. CMR: fragtfører. Luftfartsloven: befordrer","Alle kalder ham speditør","Søloven: fragtfører. CMR: befordrer","Alle kalder ham afsender"],
 f:"Det er den samme rolle, men ordene er forskellige. Søloven § 251 siger transportør. CMR-loven siger fragtfører. Luftfartsloven siger befordrer. NSAB siger speditør. CIM siger carrier. Til eksamen skal du bruge det ord, der hører til den lov, du arbejder med.",
 p:"SL § 251, CMR § 4, LFL § 106 ff."},
{k:"former", q:"Hvilken konvention bygger luftfartslovens kapitel 9 på?",
 o:["Montreal-konventionen","Haag-Visby-reglerne","CMR-konventionen","COTIF"],
 f:"Luftfartslovens kapitel 9 bygger på Montreal-konventionen fra 1999, som erstattede Warszawa-konventionen fra 1929. Haag-Visby-reglerne ligger bag søloven. CMR-konventionen ligger bag CMR-loven. COTIF og CIM gælder for tog.",
 p:"LFL § 90 og Karnov-note 249."},
{k:"former", q:"Hvilke regler ligger bag søloven kapitel 13?",
 o:["Haag-Visby-reglerne (konnossementskonventionen af 1924 med protokoller fra 1968 og 1979)","Montreal-konventionen","Hamburg-reglerne","CMR-konventionen"],
 f:"Søloven § 251 nr. 6 siger, at konventionen er den internationale konvention af 1924 om konnossementer, ændret ved protokollerne af 1968 og 1979. Det kaldes Haag-Visby-reglerne. Ifølge Karnov valgte de nordiske lande ikke de nyere Hamburg-regler, fordi Danmarks handelspartnere ikke havde tiltrådt dem.",
 p:"SL § 251 nr. 6. Karnov-note 503."},
];
